{
  "image_generation_prompt": {
    "subject": {
      "description": "Young woman with a strong resemblance to {argument name="celebrity resemblance" default="Margot Robbie"}.",
      "hair": "Pulled back into a soft, sleek bun with a subtle light blue ribbon; smooth texture with fine wisps near the ears.",
      "face": "Neutral, high-fashion expression; soft dewy skin texture with visible pores and natural light catching the cheekbones.",
      "body": "Slender and elegant physique; smooth skin texture on the legs and shoulders with soft-focus depth."
    },
    "attire": {
      "clothing": "Floral tapestry corset with lace trim and ribbon lacing; paired with a pale yellow pleated mini-skirt in a lightweight fabric; sheer white opera-length gloves and white lace-knit knee-high socks with small bows.",
      "style": "Coquette-meets-Rococo High Fashion."
    },
    "styling_and_accessories": {
      "jewelry": [
        "Delicate silver drop earrings",
        "Ornate silver hand mirror resting on the seat",
        "White floral bouquet in a silver pedestal vase"
      ]
    },
    "environment": {
      "setting": "An opulent, vintage-inspired interior featuring a white ornate fireplace mantel and a white paneled door.",
      "background": "A large gold-framed ornate mirror reflecting a red fringed lampshade; soft floral patterned sofa covered with a white lace throw.",
      "water": "None"
    },
    "pose": {
      "posture": "Seated gracefully on the back of a sofa with knees tucked toward the chest.",
      "arms": "One hand gently touching the chin in a thoughtful gesture; the other arm extended behind, resting on the lace fabric.",
      "angle": "Eye-level, full-body shot."
    },
    "lighting_and_mood": {
      "lighting": "Soft, diffused indoor lighting creating gentle shadows and a bright, airy atmosphere.",
      "mood": "Ethereal, romantic, and cinematic.",
      "colors": "Pastel palette of cream, pale yellow, and sage green, contrasted with gold accents and a pop of deep red in the reflection."
    },
    "camera_and_technical": {
      "style": "Ultra Photorealistic, RAW photo.",
      "lens": "50mm prime lens for natural proportions.",
      "aperture": "f/2.8 for a slight softening of the background while keeping the subject sharp.",
      "quality_tags": [
        "8k resolution",
        "highly detailed",
        "volumetric lighting",
        "ray tracing reflections",
        "hyper-realistic texture",
        "Hasselblad photography"
      ]
    }
  }
}

